/**
 * Forward-only migration runner. SQL files are generated by drizzle-kit from
 * schema.ts (plus hand-written custom migrations) and bundled at build time,
 * so the packaged app needs no migrations folder on disk. There is never a
 * "down" migration: going back means restoring the backup taken right before.
 */
import type { Sqlite } from './connection'

const files = import.meta.glob('./migrations/*.sql', { query: '?raw', import: 'default', eager: true }) as Record<
  string,
  string
>

export interface Migration {
  name: string
  statements: string[]
}

export const MIGRATIONS: Migration[] = Object.entries(files)
  .map(([path, sqlText]) => ({
    name: path.replace(/^.*\//, '').replace(/\.sql$/, ''),
    statements: sqlText
      .split('--> statement-breakpoint')
      .map((s) => s.trim())
      .filter((s) => s.length > 0)
  }))
  .sort((a, b) => a.name.localeCompare(b.name))

export const LATEST_SCHEMA_VERSION = MIGRATIONS[MIGRATIONS.length - 1]?.name ?? 'none'

function ensureMigrationsTable(db: Sqlite): void {
  db.exec('CREATE TABLE IF NOT EXISTS _migrations (name TEXT PRIMARY KEY NOT NULL, applied_at TEXT NOT NULL)')
}

export function appliedMigrations(db: Sqlite): string[] {
  ensureMigrationsTable(db)
  return (db.prepare('SELECT name FROM _migrations ORDER BY name').all() as { name: string }[]).map((r) => r.name)
}

export function pendingMigrations(db: Sqlite): Migration[] {
  const applied = new Set(appliedMigrations(db))
  return MIGRATIONS.filter((m) => !applied.has(m.name))
}

export function currentSchemaVersion(db: Sqlite): string {
  const applied = appliedMigrations(db)
  return applied[applied.length - 1] ?? 'none'
}

/**
 * Applies pending migrations, each in its own transaction. Foreign keys are
 * switched off during a migration (needed for SQLite table rebuilds) and
 * checked before commit, so a migration can never leave dangling references.
 */
export function runMigrations(db: Sqlite, now: () => Date = () => new Date()): string[] {
  const pending = pendingMigrations(db)
  const applied: string[] = []
  for (const migration of pending) {
    db.pragma('foreign_keys = OFF')
    try {
      db.transaction(() => {
        for (const statement of migration.statements) db.exec(statement)
        const violations = db.pragma('foreign_key_check') as unknown[]
        if (violations.length > 0) {
          throw new Error(`Migration ${migration.name} left ${violations.length} foreign key violations`)
        }
        db.prepare('INSERT INTO _migrations (name, applied_at) VALUES (?, ?)').run(
          migration.name,
          now().toISOString()
        )
      })()
    } finally {
      db.pragma('foreign_keys = ON')
    }
    applied.push(migration.name)
  }
  return applied
}
